message.content:
{
  "title": "The Mirror Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a cracked map of the ruined city.",
      "visual_description": "Mara stands on a rubble-strewn hill overlooking the ruined royal city, her ink-stained coat flapping in the wind as she traces a route on a worn parchment with her compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver joins Mara, swimming out of a shattered window.",
      "visual_description": "A clear diving helmet emerges from a broken window in a collapsed tower, the coat reflecting the twisted spires behind, as the Glass Diver steps out onto the stones.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a dark archway.",
      "visual_description": "Inside a crumbling archway, an oil lamp with a single glowing eye in its flame hovers, casting eerie shadows on the walls as it speaks in a low voice.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scampers ahead, key-wind tail spinning.",
      "visual_description": "A small metal fox with blue glass eyes darts across broken cobblestones, its key-wind tail whirring as it disappears around a corner.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The group approaches the castle gates, now twisted and rusted.",
      "visual_description": "Massive iron gates hang askew on broken hinges, their surfaces covered in rust and old royal banners tattered in the wind, with Mara and the Glass Diver peering through.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The Sleeping Tax Collector snores on a stack of ledgers near the gate.",
      "visual_description": "A figure dozes on a pile of stamped papers, using a ledger book as a pillow, papers stuck to his sleeves, oblivious to the group passing by.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame flickers rapidly as it hovers near a crooked tower with dark, shimmering windows; its eye narrows in the light.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox triggers a trap, a magic door sealing behind them.",
      "visual_description": "As the Tin Fox steps on a loose stone, a stone door etched with glowing runes slides shut from the archway, blocking their path back.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Mara consults her compass to find a way through the maze.",
      "visual_description": "Mara holds her brass compass aloft, squinting at the needle as it spins erratically, the ink on her coat smudged from the effort.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver peers through a reflective puddle to scout ahead.",
      "visual_description": "Kneeling by a murky puddle, the Glass Diver presses his helmet close to the surface, seeing a distorted image of a patrol of armored figures in the reflection.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp reveals a hidden passage behind a tapestry.",
      "visual_description": "The lamp's glow illuminates a faded royal tapestry hanging on a wall, behind which a narrow passage is revealed as the fabric sways.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Tin Fox disables a creaking door mechanism.",
      "visual_description": "The metal fox inserts its tail into a gear mechanism on a heavy door, the key turning with a click, silencing the grinding noise.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector wakes briefly, stamping a paper, then falls asleep again.",
      "visual_description": "Startled by the group's footsteps, the tax collector half-opens his eyes, mechanically stamps a paper from his sleeve, and slumps back onto the ledger pile.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols march past a broken colonnade.",
      "visual_description": "A line of faceless armored figures clanks through a shattered colonnade, their footsteps echoing as the group hides behind a toppled pillar.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver swims through a mirror to unlock a magic door.",
      "visual_description": "Pressing his hand against a full-length mirror, the Glass Diver's image ripples and he steps through, emerging on the other side to throw a bolt on a stone door.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The Oracle Lamp guides them to a broken bridge leading out of the city.",
      "visual_description": "The lamp's flame points toward a crumbling stone bridge spanning a deep chasm, its far end obscured in mist.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The Tin Fox holds a support as the group crosses the bridge.",
      "visual_description": "As the bridge trembles, the Tin Fox braces its metal legs against a loosened stone, holding a rope steady for the others to cross.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Mara looks back at the city as they escape across the bridge.",
      "visual_description": "Standing safely on the far edge, Mara turns to see the ruined city silhouetted against the dusk sky, the bridge behind them cracking and collapsing into the abyss.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

